var createTaskLineModal = (app, allTasks, onSaveSettings) => {
  let resolvePromise;
  const waitForClose = new Promise((resolve, _) => {
    resolvePromise = resolve;
  });
  const onSubmit = (updatedTasks) => {
    const line = updatedTasks.map((task2) => task2.toFileLineString()).join("\n");
    resolvePromise(line);
  };
  const onCancel = () => {
    resolvePromise("");
  };
  const task = taskFromLine({ line: "", path: "" });
  const taskModal = new TaskModal({
    app,
    task,
    onSaveSettings,
    onSubmit,
    onCancel,
    allTasks
  });
  taskModal.open();
  return waitForClose;
};

